// Hedged read: send a second request if the first is slower than p95
async function hedgedGet(replicas: string[], key: string, p95Ms = 40) {
  const ctl = replicas.map(() => new AbortController());
  const call = (i: number) => fetchFrom(replicas[i], key, ctl[i].signal);
  const first = call(0);
  const timer = new Promise((_, rej) => setTimeout(rej, p95Ms));
  try { return await Promise.race([first, timer]); }
  catch { return await Promise.race([first, call(1)]); }
  finally { ctl.forEach(c => c.abort()); }
}

