async function withRetry<T>(fn: () => Promise<T>, maxAttempts = 5) {
  const base = 100, cap = 30_000;
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (err: any) {
      if (!isRetryable(err) || attempt + 1 >= maxAttempts) throw err;
      const delay = Math.min(cap, base * 2 ** attempt);
      await sleep(err.retryAfterMs ?? delay);  // honor Retry-After
    }
  }
}

