# Meter-style leaky bucket
class Leaky:
    def __init__(self, rate, size):
        self.rate, self.size = rate, size
        self.level, self.t = 0.0, time.monotonic()

    def allow(self):
        now = time.monotonic()
        self.level = max(0.0, self.level - (now - self.t) * self.rate)
        self.t = now
        if self.level + 1 > self.size:
            return False
        self.level += 1
        return True

