# One gossip round, every 1s
def gossip_round(self):
    self.table[self.id].heartbeat += 1
    for peer in random.sample(self.live_peers(), k=3):     # fanout = 3
        peer.merge(self.table)

def merge(self, remote):
    for node, r in remote.items():
        if r.heartbeat > self.table[node].heartbeat:
            self.table[node] = r._replace(seen=now())

