// build a Merkle tree over bucketed keys
function build(buckets: string[][]): string[][] {
  let level = buckets.map(b => sha256(b.sort().join('\n')));
  const levels = [level];
  while (level.length > 1) {
    const next: string[] = [];
    for (let i = 0; i < level.length; i += 2)
      next.push(sha256(level[i] + (level[i + 1] ?? level[i])));
    levels.push((level = next));
  }
  return levels; // levels.at(-1)[0] is the root
}

const EPOCH = 1700000000000n;
let lastTs = -1n, seq = 0n;
function nextId(dc: bigint, machine: bigint): bigint {
  let ts = BigInt(Date.now());
  if (ts < lastTs) throw new Error('clock moved backward');
  if (ts === lastTs) {
    seq = (seq + 1n) & 4095n;
    if (seq === 0n) while (ts <= lastTs) ts = BigInt(Date.now());
  } else seq = 0n;
  lastTs = ts;
  return ((ts - EPOCH) << 22n) | (dc << 17n) | (machine << 12n) | seq;
}

