def search(head, level, key):
    x = head
    for i in range(level - 1, -1, -1):    # top level down
        while x.next[i] and x.next[i].key < key:
            x = x.next[i]
    return x.next[0]

def match_buy(book, order):
    fills = []
    # asks: sorted ascending, each level is a FIFO deque
    while order.qty > 0 and book.asks and book.asks.best_price() <= order.price:
        level = book.asks.best_level()
        resting = level.queue[0]
        qty = min(order.qty, resting.qty)
        fills.append((order.id, resting.id, resting.price, qty))
        order.qty -= qty
        resting.qty -= qty
        if resting.qty == 0: level.pop_front()
    if order.qty > 0: book.bids.add(order)
    return fills

